INSERT INTO claim_details (claim_number, event_time, location, summary, client_email, client_phone, policy_number, coverage, deductible, coverage_limit, photos) VALUES ('CLM-1001', 'May 14th, 2026, at about 8:40 AM', 'Sheikh Zayed Road, northbound near Exit 41, Dubai', 'The insured, Alice Nguyen, was stopped at a red light when the vehicle behind her failed to brake in time and struck the rear of her 2023 Toyota Corolla. The rear bumper, boot lid and one tail light were damaged. Dubai Police attended and issued a report; the other driver accepted fault at the scene. No one was injured. Ms. Nguyen has submitted the police report and photos of the damage.', 'alice.nguyen@example.com', '+971 50 412 3381', 'AU-48213907', 'Comprehensive auto', 'USD 1,000', 'USD 150,000', 'car-accident-1.jpg,car-accident-2.jpg');
INSERT INTO claim_details (claim_number, event_time, location, summary, client_email, client_phone, policy_number, coverage, deductible, coverage_limit, photos) VALUES ('CLM-1002', 'May 9th, 2026, during the evening storm', 'Villa 14, Street 7, Al Barsha 2, Dubai', 'High winds during an evening storm lifted a section of the roof tiles on the insured''s villa. Rain entered through the gap and damaged the ceiling and flooring of the upstairs bedroom. A contractor made the roof watertight the next morning. Marcus Feld provided the contractor''s invoice and photos taken before the temporary repair.', 'marcus.feld@example.com', '+971 55 208 7712', 'HO-30571264', 'Homeowners, buildings and contents', 'USD 2,500', 'USD 1,500,000', 'roof-damage.jpg');
INSERT INTO claim_details (claim_number, event_time, location, summary, client_email, client_phone, policy_number, coverage, deductible, coverage_limit, photos) VALUES ('CLM-1003', 'June 1st, 2026, at about 6:15 PM', 'Car park level 2, Mall of the Emirates, Dubai', 'While the insured, Priya Raman, was shopping, another vehicle scraped the driver''s side of her parked 2021 Nissan Altima, leaving a long scratch and a dented rear door. The other driver left a note with contact details. Ms. Raman has asked for a repair estimate from her usual garage.', 'priya.raman@example.com', '+971 52 774 1093', 'AU-48219451', 'Comprehensive auto', 'USD 1,000', 'USD 150,000', 'car-accident-3.jpg');
INSERT INTO claim_details (claim_number, event_time, location, summary, client_email, client_phone, policy_number, coverage, deductible, coverage_limit, photos) VALUES ('CLM-1004', 'April 22nd, 2026, at about 3:00 PM', 'Townhouse 6, Arabian Ranches, Dubai', 'A short hailstorm broke two front window panes and cracked the glass door to the garden of the insured''s townhouse. Tom Becker had the openings boarded up the same day and asked a glazier for a quote. He has since uploaded a revised repair estimate from Falcon Glass & Home Repairs LLC.', 'tom.becker@example.com', '+971 56 330 2847', 'HO-30578812', 'Homeowners, buildings and contents', 'USD 2,500', 'USD 1,500,000', 'storm-house.jpg');
INSERT INTO claim_details (claim_number, event_time, location, summary, client_email, client_phone, policy_number, coverage, deductible, coverage_limit, photos) VALUES ('CLM-1005', 'March 30th, 2026', 'Abu Dhabi', 'Sofia Alvarez, the named beneficiary, notified Parasol of the death of the insured, her husband, after an illness. She submitted the death certificate, the policy schedule and her identification. The documents were verified and the claim was approved.', 'sofia.alvarez@example.com', '+971 50 991 4402', 'LI-77120395', 'Term life', 'None', 'Sum assured on the policy schedule', '');
INSERT INTO claim_details (claim_number, event_time, location, summary, client_email, client_phone, policy_number, coverage, deductible, coverage_limit, photos) VALUES ('CLM-1006', 'January 20th, 2026, at about 7:50 AM', 'Al Safa roundabout, Dubai', 'Entering the roundabout, the insured, Michael Turner, was struck on the passenger side by a van that did not give way. The passenger doors and front wing of his 2022 Honda Accord were damaged and the airbag on that side deployed. Dubai Police issued a report naming the van driver at fault.', 'michael.turner@example.com', '+971 55 619 2034', 'AU-48220376', 'Comprehensive auto', 'USD 1,000', 'USD 150,000', 'car-accident-2.jpg');
INSERT INTO claim_details (claim_number, event_time, location, summary, client_email, client_phone, policy_number, coverage, deductible, coverage_limit, photos) VALUES ('CLM-1007', 'August 14th, 2025, overnight', 'Apartment 1203, Marina Heights Tower, Dubai Marina', 'A supply pipe burst behind the kitchen wall overnight while the insured, Karen Foster, was away. Water spread across the kitchen and living room and leaked into the flat below. Building maintenance shut off the supply in the morning. Ms. Foster provided the plumber''s report and photos of the damage.', 'karen.foster@example.com', '+971 52 803 5560', 'HO-30562219', 'Homeowners, buildings and contents', 'USD 2,500', 'USD 1,500,000', 'flood-damage.jpg');
INSERT INTO claim_details (claim_number, event_time, location, summary, client_email, client_phone, policy_number, coverage, deductible, coverage_limit, photos) VALUES ('CLM-1008', 'December 28th, 2025, at about 5:30 PM', 'Emirates Road, near the Al Awir interchange, Dubai', 'In heavy evening traffic, a truck changed lanes into the insured''s lane and pushed his 2020 Hyundai Tucson into the barrier. David Park was shaken but uninjured. The vehicle was towed from the scene; the front and the driver''s side are badly damaged.', 'david.park@example.com', '+971 50 228 6719', 'AU-48207733', 'Comprehensive auto', 'USD 1,000', 'USD 150,000', 'car-wreck.jpg');
INSERT INTO claim_details (claim_number, event_time, location, summary, client_email, client_phone, policy_number, coverage, deductible, coverage_limit, photos) VALUES ('CLM-1009', 'December 1st, 2025, at about 9:20 PM', 'Villa 3, Jumeirah Park, Dubai', 'A pan fire in the kitchen of the insured''s villa spread to the extractor hood and cabinets before the fire service put it out. Smoke damaged the ground floor. Emily Watson and her family were unhurt and are staying with relatives while the house is cleaned. The fire service report is attached to the claim.', 'emily.watson@example.com', '+971 56 114 9087', 'HO-30580041', 'Homeowners, buildings and contents', 'USD 2,500', 'USD 1,500,000', '');
INSERT INTO claim_details (claim_number, event_time, location, summary, client_email, client_phone, policy_number, coverage, deductible, coverage_limit, photos) VALUES ('CLM-1010', 'October 3rd, 2025, at about 8:15 AM', 'Al Khail Road, southbound, Dubai', 'The insured, Robert Chen, was hit from behind in slow-moving traffic and pushed into the car in front. Both the front and rear of his 2022 Mazda CX-5 were damaged. The two other drivers and Mr. Chen exchanged details, and the police report places the fault with the driver behind.', 'robert.chen@example.com', '+971 55 470 1128', 'AU-48201566', 'Comprehensive auto', 'USD 1,000', 'USD 150,000', 'car-accident-1.jpg');
INSERT INTO claim_details (claim_number, event_time, location, summary, client_email, client_phone, policy_number, coverage, deductible, coverage_limit, photos) VALUES ('CLM-1011', 'September 22nd, 2025, at about 2:10 AM', 'Hatta Road, near Hatta, Dubai', 'The insured''s 2019 Ford Mustang left the road on a bend in the early hours and was written off. James Rodriguez reported that he was driving. The investigation found that the vehicle was being used for an unlicensed race at the time, which the policy excludes, and the claim was denied.', 'james.rodriguez@example.com', '+971 50 667 3045', 'AU-48198320', 'Comprehensive auto', 'USD 1,000', 'USD 150,000', 'car-wreck.jpg');
INSERT INTO claim_details (claim_number, event_time, location, summary, client_email, client_phone, policy_number, coverage, deductible, coverage_limit, photos) VALUES ('CLM-1012', 'January 8th, 2026, after heavy rain', 'Villa 22, Mirdif, Dubai', 'Days of unusually heavy rain overwhelmed the drainage around the insured''s villa and water entered the ground floor. Flooring, skirting and furniture were damaged. Patricia O''Brien has provided photos and a cleaning contractor''s assessment.', 'patricia.obrien@example.com', '+971 52 391 8806', 'HO-30566578', 'Homeowners, buildings and contents', 'USD 2,500', 'USD 1,500,000', 'flood-damage.jpg');
INSERT INTO claim_details (claim_number, event_time, location, summary, client_email, client_phone, policy_number, coverage, deductible, coverage_limit, photos) VALUES ('CLM-1013', 'November 15th, 2025', 'Sharjah', 'Linda Park, the named beneficiary, notified Parasol of the death of the insured, her father. The death certificate, the policy schedule and proof of identity were provided and verified, and the claim was approved.', 'linda.park@example.com', '+971 56 702 4419', 'LI-77109834', 'Term life', 'None', 'Sum assured on the policy schedule', '');
INSERT INTO claim_details (claim_number, event_time, location, summary, client_email, client_phone, policy_number, coverage, deductible, coverage_limit, photos) VALUES ('CLM-1014', 'June 10th, 2026, at about 1:30 PM', 'Car park, Dubai Festival City Mall', 'A reversing vehicle clipped the insured''s parked 2023 Kia Sportage, breaking the side mirror and denting the driver''s door. Dennis Wright found the damage on his return; the mall''s security office is retrieving the camera footage.', 'dennis.wright@example.com', '+971 50 845 2290', 'AU-48224410', 'Comprehensive auto', 'USD 1,000', 'USD 150,000', 'car-accident-3.jpg');
INSERT INTO claim_details (claim_number, event_time, location, summary, client_email, client_phone, policy_number, coverage, deductible, coverage_limit, photos) VALUES ('CLM-1015', 'February 17th, 2026, during a wind storm', 'Villa 9, The Springs 4, Dubai', 'Strong winds tore off part of the roof covering over the insured''s garage and damaged the gutter. Grace Kim had a contractor secure the roof the same evening and has submitted the invoice and photos.', 'grace.kim@example.com', '+971 55 936 1174', 'HO-30569957', 'Homeowners, buildings and contents', 'USD 2,500', 'USD 1,500,000', 'roof-damage.jpg');
INSERT INTO claim_details (claim_number, event_time, location, summary, client_email, client_phone, policy_number, coverage, deductible, coverage_limit, photos) VALUES ('CLM-1016', 'October 29th, 2025', 'Dubai', 'Samuel Ortiz, the named beneficiary, notified Parasol of the death of the insured, his brother, in a road accident abroad. The death certificate has been received; the translated police report from the country of the accident is still awaited.', 'samuel.ortiz@example.com', '+971 52 258 6603', 'LI-77116270', 'Term life', 'None', 'Sum assured on the policy schedule', '');
INSERT INTO claim_details (claim_number, event_time, location, summary, client_email, client_phone, policy_number, coverage, deductible, coverage_limit, photos) VALUES ('CLM-1017', 'March 5th, 2026, at about 11:00 AM', 'Al Wasl Road, Jumeirah, Dubai', 'A delivery motorcycle hit the side of the insured''s 2022 Volkswagen Golf while she was turning into a side street. Nina Petrova''s front door and wing were scratched and dented. The rider was uninjured and the police report places the fault with him.', 'nina.petrova@example.com', '+971 56 481 7735', 'AU-48214658', 'Comprehensive auto', 'USD 1,000', 'USD 150,000', 'car-accident-2.jpg');
INSERT INTO claim_details (claim_number, event_time, location, summary, client_email, client_phone, policy_number, coverage, deductible, coverage_limit, photos) VALUES ('CLM-1018', 'September 12th, 2025, discovered', 'Apartment 507, Al Nahda 1, Dubai', 'Hassan Ali reported water damage to the bathroom walls and floor of his apartment. The plumber''s report found a slow leak from a shower seal over many months. Gradual leakage is excluded under the policy, and the claim was denied.', 'hassan.ali@example.com', '+971 50 136 9928', 'HO-30559310', 'Homeowners, buildings and contents', 'USD 2,500', 'USD 1,500,000', 'flood-damage.jpg');
INSERT INTO claim_details (claim_number, event_time, location, summary, client_email, client_phone, policy_number, coverage, deductible, coverage_limit, photos) VALUES ('CLM-1019', 'April 30th, 2026, at about 4:45 PM', 'Al Wasl Road, Umm Suqeim, Dubai', 'The insured, Olivia Brooks, had a low-speed collision with a taxi that pulled out of a parking space. The front bumper of her 2024 Toyota Yaris is cracked. The taxi company has accepted responsibility in writing.', 'olivia.brooks@example.com', '+971 52 640 2259', 'AU-48221897', 'Comprehensive auto', 'USD 1,000', 'USD 150,000', 'car-accident-3.jpg');
INSERT INTO claim_details (claim_number, event_time, location, summary, client_email, client_phone, policy_number, coverage, deductible, coverage_limit, photos) VALUES ('CLM-1020', 'June 18th, 2026', 'Ras Al Khaimah', 'Ethan Cole, the named beneficiary, notified Parasol of the death of the insured, his mother. The death certificate and policy schedule have been submitted; proof of identity is still to come.', 'ethan.cole@example.com', '+971 55 503 3816', 'LI-77125561', 'Term life', 'None', 'Sum assured on the policy schedule', '');
INSERT INTO claim_details (claim_number, event_time, location, summary, client_email, client_phone, policy_number, coverage, deductible, coverage_limit, photos) VALUES ('CLM-1021', 'February 2nd, 2026, during a storm', 'Villa 31, Al Furjan, Dubai', 'A storm brought down a large tree in the insured''s garden onto the boundary wall and the pergola, which collapsed onto the patio. Maria Santos has submitted photos and a quote for the rebuild.', 'maria.santos@example.com', '+971 56 925 0471', 'HO-30567708', 'Homeowners, buildings and contents', 'USD 2,500', 'USD 1,500,000', 'storm-house.jpg');
INSERT INTO claim_details (claim_number, event_time, location, summary, client_email, client_phone, policy_number, coverage, deductible, coverage_limit, photos) VALUES ('CLM-1022', 'November 27th, 2025, at about 7:20 PM', 'Business Bay, Dubai', 'While the insured''s 2021 Tesla Model 3 was parked on the street, a passing vehicle hit the rear corner and drove off. Kevin Zhang reported it to the police the same evening; a witness gave a partial number plate.', 'kevin.zhang@example.com', '+971 50 718 6642', 'AU-48212045', 'Comprehensive auto', 'USD 1,000', 'USD 150,000', 'car-accident-1.jpg');
INSERT INTO claim_details (claim_number, event_time, location, summary, client_email, client_phone, policy_number, coverage, deductible, coverage_limit, photos) VALUES ('CLM-1023', 'December 19th, 2025', 'Dubai', 'Rachel Green, the named beneficiary, notified Parasol of the death of the insured, her husband. The cause of death is under medical review because the policy was taken out less than two years earlier.', 'rachel.green@example.com', '+971 52 117 4485', 'LI-77118843', 'Term life', 'None', 'Sum assured on the policy schedule', '');
INSERT INTO claim_details (claim_number, event_time, location, summary, client_email, client_phone, policy_number, coverage, deductible, coverage_limit, photos) VALUES ('CLM-1024', 'May 25th, 2026, after a storm', 'Villa 4, Al Twar 3, Dubai', 'Parts of the roof waterproofing over the insured''s villa failed after a storm and water marked the ceilings of two rooms. Daniel Mbeki has submitted photos; an assessor visit is still to be booked.', 'daniel.mbeki@example.com', '+971 55 362 9150', 'HO-30581276', 'Homeowners, buildings and contents', 'USD 2,500', 'USD 1,500,000', 'roof-damage.jpg');
INSERT INTO claim_details (claim_number, event_time, location, summary, client_email, client_phone, policy_number, coverage, deductible, coverage_limit, photos) VALUES ('CLM-1025', 'October 15th, 2025, at about 10:30 PM', 'Al Ittihad Road, Sharjah', 'The insured''s 2018 BMW 3 Series hit the central barrier. Laura Bianchi reported the accident three weeks later, and the police report shows the car was being driven by an unlisted driver, which the policy does not cover. The claim was denied.', 'laura.bianchi@example.com', '+971 56 249 7013', 'AU-48203389', 'Comprehensive auto', 'USD 1,000', 'USD 150,000', 'car-accident-2.jpg');
INSERT INTO claim_details (claim_number, event_time, location, summary, client_email, client_phone, policy_number, coverage, deductible, coverage_limit, photos) VALUES ('CLM-1026', 'January 31st, 2026, during a storm', 'Villa 18, Emirates Hills, Dubai', 'A severe storm damaged the roof and broke windows at the insured''s villa, and rain entered several rooms. George Adams arranged emergency repairs and has provided the contractors'' invoices and photos.', 'george.adams@example.com', '+971 50 584 3361', 'HO-30570183', 'Homeowners, buildings and contents', 'USD 2,500', 'USD 1,500,000', 'storm-house.jpg,roof-damage.jpg');
INSERT INTO claim_details (claim_number, event_time, location, summary, client_email, client_phone, policy_number, coverage, deductible, coverage_limit, photos) VALUES ('CLM-1027', 'September 8th, 2025', 'Fujairah', 'Chloe Martin, the named beneficiary, notified Parasol of the death of the insured, her father. All documents were provided and verified, and the claim was approved.', 'chloe.martin@example.com', '+971 52 896 2207', 'LI-77104119', 'Term life', 'None', 'Sum assured on the policy schedule', '');
INSERT INTO claim_details (claim_number, event_time, location, summary, client_email, client_phone, policy_number, coverage, deductible, coverage_limit, photos) VALUES ('CLM-1028', 'March 22nd, 2026, at about 9:05 AM', 'Al Khail Road, near Meydan, Dubai', 'The insured, Victor Osei, braked for a sudden stop in traffic and was hit from behind. The rear of his 2023 Mitsubishi Outlander is damaged. The other driver''s insurer has been notified.', 'victor.osei@example.com', '+971 55 107 5528', 'AU-48216472', 'Comprehensive auto', 'USD 1,000', 'USD 150,000', 'car-accident-1.jpg');
INSERT INTO claim_details (claim_number, event_time, location, summary, client_email, client_phone, policy_number, coverage, deductible, coverage_limit, photos) VALUES ('CLM-1029', 'April 11th, 2026, overnight', 'Villa 12, Al Barsha 3, Dubai', 'An air-conditioning drain line blocked and overflowed in the upstairs hallway of the insured''s villa overnight. Water came through the ceiling into the living room below. Amara Okafor has submitted photos and the maintenance company''s report.', 'amara.okafor@example.com', '+971 56 433 8892', 'HO-30574405', 'Homeowners, buildings and contents', 'USD 2,500', 'USD 1,500,000', 'flood-damage.jpg');
INSERT INTO claim_details (claim_number, event_time, location, summary, client_email, client_phone, policy_number, coverage, deductible, coverage_limit, photos) VALUES ('CLM-1030', 'June 27th, 2026', 'Dubai', 'Frank Miller, the named beneficiary, notified Parasol of the death of the insured, his wife. The claim has been opened and the document checklist sent to him.', 'frank.miller@example.com', '+971 50 940 1176', 'LI-77127708', 'Term life', 'None', 'Sum assured on the policy schedule', '');
INSERT INTO claim_details (claim_number, event_time, location, summary, client_email, client_phone, policy_number, coverage, deductible, coverage_limit, photos) VALUES ('CLM-1031', 'June 20th, 2026, at about 11:20 PM', 'Car park, Ibn Battuta Mall, Dubai', 'The insured, Daniel Brooks, returned to his parked 2022 Honda Civic late in the evening to find the rear bumper dented and a tail light broken. Nobody left a note. He reported it through the portal the same night.', 'daniel.brooks@example.com', '+971 52 571 6634', 'AU-48226119', 'Comprehensive auto', 'USD 1,000', 'USD 150,000', 'car-accident-3.jpg');
